import {bondPrice} from './calculations.js';
export const guidedLessons=[];
function addLesson(topic,id,title,concepts,context,teaching,question,options,correct,explanation,calculations=[]){
 guidedLessons.push({id,topic,title,conceptIds:concepts.split(' ').map(x=>topic+'-'+x),context,teaching,question,options,correct,explanation,calculations});
}
addLesson('bonds','promise','The promise','face time',
 'Maya buys Cedar Workshop’s three-year bond. For this example, the contract has $1,000 face value and a 5% annual coupon rate, paid once each year.',
 'Face value is the principal the company promises to repay at maturity. The coupon is the interest payment. A payment timeline separates those two claims: the earlier years pay interest, and the last year pays both interest and principal.',
 'Maya resells the bond at a different market price. What happens to the principal the company promises to repay?',
 ['It becomes the resale price','It remains the $1,000 contractual face value','It becomes the coupon payment'],1,
 'The resale transfers ownership; it does not rewrite the company’s contract. Principal remains the agreed face value.',['bond-coupon']);
addLesson('bonds','price','The price can change','market price',
 'Keep Cedar Workshop’s bond: $1,000 principal, a 5% annual coupon rate, and three annual payments remaining. These are example contract terms. Now assume comparable traded bonds imply a 6% required annual yield.',
 'The promised payments stay fixed. Buyers requiring a higher yield must pay less for those payments. Market prices imply yields; the issuer cannot require investors to accept its preferred price. The worked example discounts each payment rather than inventing a new coupon.',
 'Comparable required yields rise further while this bond’s payments stay fixed. What should happen to its price?',
 ['It should fall','Its coupon must increase','It should rise'],0,
 'Paying less for the same future payments increases the buyer’s implied yield. The contract’s coupon does not change.',['bond-price']);
addLesson('bonds','yield','Coupon rate and yield','ytminverse current reinvest',
 'Two of Cedar Workshop’s annual coupons have already been paid. Exactly one year remains. Keep the example’s $1,000 principal and 5% annual coupon rate; assume the buyer requires a 6% one-year return and the final payment arrives in full.',
 'The coupon rate describes the contract. Yield describes the return implied by the purchase price and future payments. Current yield uses only annual coupon divided by price. Yield to maturity also includes principal repayment and timing. For several remaining coupons, earning YTM as a terminal compound return additionally depends on coupon reinvestment.',
 'Why can a buyer’s yield exceed the unchanged coupon rate?',
 ['The issuer secretly increases the coupon','Buying below face value adds a gain when principal is repaid','Yield is always guaranteed even if the issuer defaults'],1,
 'The buyer receives the coupon and a repayment larger than the discounted purchase price. For a risky issuer, promised YTM still differs from probability-weighted expected return.',['current-yield']);
addLesson('bonds','waiting','Money across time','annuity',
 'Maya compares an amount received today with a promised amount received later. She also considers a contract making equal year-end payments.',
 'Discounting translates future cash into today’s value using an appropriate rate. Compounding runs the calculation in the opposite direction. An annuity stops after a specified number of payments; a perpetuity continues indefinitely. Match the rate to the payment periods and distinguish end-of-period from beginning-of-period payments.',
 'Two otherwise identical certain payments arrive at different dates. With a positive discount rate, which is worth more today?',
 ['The later payment','The earlier payment','Waiting never affects present value'],1,
 'The earlier payment is discounted for less time. That timing difference matters even when the amounts are identical.',['pv','zero','compound','annuity']);
addLesson('bonds','curve','A curve of rates','spot forward curve',
 'Cedar Workshop owes payments at several future dates. Maya notices that comparable safe investments have different yields at different maturities.',
 'A spot rate discounts a payment at one maturity. A bond’s YTM compresses multiple payments into one implied rate. Forward rates connect investments across successive periods through no-arbitrage; they are not certain predictions. The yield curve also reflects term premiums and demand. An inversion can warn of recession risk without fixing its timing.',
 'Does today’s implied forward interest rate tell Maya exactly what the future spot rate will be?',
 ['Yes, it is a guaranteed forecast','No, it is a pricing relationship with assumptions about risk premiums','Yes, the issuer sets it for every investor'],1,
 'The forward rate makes alternative financing paths consistent today. Future spot rates can differ.',['forward-rate']);
addLesson('bonds','sensitivity','How sensitive is the price?','duration convexity',
 'Maya compares two fixed-payment bonds after interest rates move. She needs an estimate of the price response before doing a complete repricing.',
 'Modified duration approximates sensitivity to a small yield change. Macaulay duration is the cash-flow-weighted waiting time. Convexity accounts for curvature in the price–yield relation. Larger moves, changes across different parts of the yield curve, and embedded prepayment or call options make a single duration estimate less reliable.',
 'When a yield move is large, why should Maya be cautious about a duration-only estimate?',
 ['Duration is a default probability','The price–yield relationship is curved and options may change cash flows','Bond prices cannot change'],1,
 'Duration is a local approximation. Convexity and the exact cash-flow structure matter as the change grows.',['duration']);
addLesson('bonds','purchasing-power','What return do you really receive?','real credit clean',
 'Maya compares a safe nominal bond with a higher-yielding corporate bond. She also checks how much she must actually pay at settlement.',
 'Inflation reduces the purchasing power of nominal receipts. Corporate spreads include expected losses, risk compensation and liquidity effects, so a larger promised yield does not automatically mean a larger expected gain. A clean quote excludes accrued coupon interest; the dirty settlement price adds it. Compare consistent cash flows, price conventions and risk.',
 'Why is the corporate bond’s higher quoted yield insufficient to establish that it is the better investment?',
 ['Higher yield eliminates default risk','Promised payments can differ from the payments actually expected','Inflation applies only to government debt'],1,
 'Default, recovery and liquidity can offset the larger promised yield. Purchasing-power effects and the price actually paid also matter.',['real-return']);
addLesson('purpose','sharing','Who bears which risk?','claims sharing innovation',
 'Cedar Workshop wants to buy equipment without placing every possible loss on its founder. It can sell equity, borrow, insure a fire risk or hedge an input price.',
 'Each contract assigns money to different people in different future states: equity shares residual gains and losses; debt promises repayments; insurance covers defined events. Pooling and shifting risks can make worthwhile activity possible. Judge an innovation by the protection and productive activity it supports after costs and fragility, rather than by its complexity.',
 'The founder buys insurance and gives up some expected income. Can this improve the founder’s welfare?',
 ['Yes, reducing a painful risk can be worth the premium','No, only the highest average dollar payoff matters','Yes, because insurance eliminates all risk from society'],0,
 'A risk-averse person can prefer a more stable outcome. The insurer takes on defined risks; it does not erase society’s losses.');
addLesson('purpose','incentives','Hidden information and incentives','adverse moral agency',
 'An insurer chooses which workshops to cover. After buying coverage, a workshop manager decides how much safety maintenance to do. Separately, a hired fund manager invests clients’ savings.',
 'Adverse selection concerns information hidden before a contract: riskier customers may be keener to buy insurance. Moral hazard concerns behavior changed by protection. A principal–agent problem arises when a decision-maker’s incentives differ from the owner’s. Deductibles, monitoring and pay design can help, with tradeoffs.',
 'An insured workshop stops maintaining fire alarms because it expects the insurer to pay. Which mechanism is at work?',
 ['Adverse selection alone','Moral hazard after obtaining protection','A market-wide change in beta'],1,
 'Coverage changed the incentive to prevent loss. A customer’s privately known risk before purchase would instead be adverse selection.');
addLesson('purpose','responsibility','Ownership and wider consequences','liability externality',
 'Cedar Workshop raises money from outside shareholders. Its lender also holds assets shared by many other financial institutions.',
 'Limited liability ordinarily protects shareholders’ personal assets beyond their investment, although guarantees and legal exceptions matter. It does not protect the investment itself. Separately, a lender trying to protect its own balance sheet can create external costs: forced sales may lower common asset prices and damage other institutions.',
 'Can a lender act rationally for itself while making the financial system less stable?',
 ['No, rational choices always benefit everyone','Yes, its asset sales can impose losses on other holders','Only if every shareholder has unlimited liability'],1,
 'The seller does not necessarily bear all the effects on other institutions. That gap between private and social costs is an externality.');
addLesson('risk','uncertainty','Average return is only part of the story','expected variance utility',
 'Maya compares investments with uncertain outcomes. She wants enough resources to meet obligations, rather than simply the most attractive average forecast.',
 'Expected return weights outcomes by their probabilities. Variance and its square root, volatility, describe dispersion around the mean; they do not capture every downside or rare event. Diminishing marginal utility means equal dollar gains and losses need not have equal welfare effects. A positive expected return remains compatible with losses.',
 'Why might Maya reject a gamble with positive expected value?',
 ['Positive expected value guarantees failure','Its downside can threaten obligations more than its upside helps','The probability-weighted average must be wrong'],1,
 'Expected utility and the ability to absorb losses matter alongside the expected dollar amount.',['expected']);
addLesson('risk','diversification','How holdings move together','correlation systematic frontier',
 'Maya owns several businesses. Some earn more when others earn less; several others all depend on the same technology sector.',
 'Portfolio risk depends on weights and joint movements, not just the number of holdings. Diversification can reduce company-specific risk while leaving economy-wide and sector exposures. The efficient frontier is the set of best mean–variance combinations under estimated inputs and constraints; uncertain correlations and expected returns make those inputs fragile.',
 'Maya adds more technology firms to an already technology-heavy portfolio. What can remain?',
 ['Common sector and recession exposure','A guarantee of independent returns','No possible loss once she has enough names'],0,
 'Company-specific diversification can improve while the portfolio retains the same common economic bets.',['portfolio']);
addLesson('risk','market-risk','Pricing exposure to the market','beta capm cml',
 'Maya compares an asset that moves strongly with the broad market with one whose unusual risks are mostly company-specific.',
 'Beta measures market covariance relative to market variance, not total risk. Basic CAPM associates expected compensation with this nondiversifiable exposure. Its security market line uses beta; the capital market line combines the risk-free asset with an efficient risky portfolio and uses total volatility. These are model benchmarks, not complete laws of actual returns.',
 'Does a low-beta asset necessarily have low total risk?',
 ['Yes, beta measures every possible risk','No, it can have large company-specific or tail risks','Yes, as long as it pays dividends'],1,
 'Beta describes a particular market relationship. Other uncertainties remain outside that measure.',['capm']);
addLesson('risk','tails','Pooling and extreme losses','lln var tails',
 'An insurer covers workshops in many locations. A catastrophe can nevertheless affect many policyholders at once, while a portfolio manager uses a statistical loss model.',
 'The law of large numbers helps stabilize averages when risks are sufficiently independent; correlated catastrophes remain. Value at Risk is a modeled loss threshold, not a worst-loss cap. Expected shortfall addresses average severity beyond a tail threshold. Fat tails, changing dependence and selected stress scenarios require more than one risk metric.',
 'A risk model gives a loss threshold at a chosen confidence level. What remains unknown from that threshold alone?',
 ['The severity of losses beyond it','Whether the portfolio has a price','Every historical return'],0,
 'A threshold says little about how damaging the tail can be. Tail measures and stress scenarios supply different information.');
addLesson('behavior','expectations','News relative to expectations','news emh walk joint',
 'Cedar Workshop reports strong earnings, yet its share price falls. Maya wonders whether the market has ignored good news.',
 'A price incorporates expectations, so even a strong result can disappoint. Weak efficiency concerns past trading data; semi-strong efficiency concerns public information. Unpredictable news is compatible with changing expected risk premiums. Tests of abnormal returns also depend on the pricing benchmark—the joint-hypothesis problem.',
 'What could explain a price decline after a strong earnings announcement?',
 ['Investors had expected an even stronger result or outlook','Strong results always force prices upward','The stock has become a bond'],0,
 'The relevant surprise is the difference from prior expectations, including future guidance—not the positive wording of the headline.');
addLesson('behavior','feedback','Stories, valuation and feedback','excess bubbles arbitrage narratives',
 'A promising technology draws attention. Rising prices attract more buyers, and optimistic stories become easier to believe.',
 'Shiller’s excess-volatility work challenges simple constant-discount-rate accounts of prices; changing discount rates and risk premiums are also possible explanations. Narrative and credit feedback can reinforce a boom. Recognizing a valuation risk does not determine when it ends: funding constraints, short-sale costs and uncertain timing limit arbitrage.',
 'Maya thinks an asset is overpriced. What does that establish about a short position?',
 ['It is guaranteed to profit immediately','Timing, financing and further price rises can still make the trade fail','Its borrowing costs are zero'],1,
 'A plausible valuation view does not make the trading path survivable or the turning point predictable.');
addLesson('behavior','judgment','Reference points and judgment','prospect anchoring disposition confidence',
 'Maya is reluctant to sell an investment below her purchase price. She confidently trades frequent tips while quickly taking gains on winners.',
 'Prospect theory describes reference-dependent gains and losses, diminishing sensitivity and probability weighting. Anchoring can make a past price dominate a forward-looking choice; the disposition effect describes selling winners while clinging to losers. Overconfidence can increase concentration and costly trading. Tax effects can matter without making the original price a valuation rule.',
 'What is a useful question when Maya is keeping a loser mainly to “get back to even”?',
 ['Would she choose this investment today given its future prospects?','Can the past purchase price force a recovery?','Does avoiding a sale eliminate the economic loss?'],0,
 'Assess the opportunity from today, including alternatives and relevant tax consequences. The historical entry price does not set future value.');
addLesson('equity','ownership','Residual ownership and financing','residual preferred capitalstructure',
 'Cedar Workshop finances assets with debt, preferred equity and ordinary shares. Maya wants to know which claim she is buying.',
 'Common equity is residual ownership: senior obligations come first. Preferred shares often have dividend and liquidation priority but different voting rights and contract terms. Capital structure allocates risk among claims. Taxes, distress and incentives make real financing choices matter even though irrelevance results provide useful idealized benchmarks.',
 'Why can the business retain some asset value while common shareholders receive nothing in liquidation?',
 ['Senior claims may absorb all available value first','Common shares guarantee repayment at face value','All claimants must receive identical amounts'],0,
 'Residual ownership receives what remains after claims with priority. Limited liability does not guarantee a recovery.');
addLesson('equity','valuation','Valuing future cash flows','gordon wacc terminal',
 'Maya values a mature business with growing payouts. She separately estimates cash available to all the firm’s capital providers.',
 'The Gordon model assumes perpetual constant dividend growth below the required equity return. A full firm valuation discounts free cash flow to the firm at the weighted average cost of capital, then reconciles debt, cash and other claims to estimate equity value. Terminal assumptions can dominate the estimate, so sensitivity matters more than spurious precision.',
 'What goes wrong with using perpetual growth at or above the required return in the Gordon model?',
 ['It falls outside the formula’s convergence assumptions','It guarantees a very cheap share','It removes the need to estimate dividends'],0,
 'The infinite discounted stream no longer yields the intended finite value. Use a defensible growth structure rather than treating the denominator as a pricing trick.',['gordon']);
addLesson('equity','ratios','Ratios and market value','pe cape marketcap',
 'Maya compares companies with different earnings histories and checks the market value of their outstanding shares.',
 'Market capitalization is share price times shares outstanding, rather than revenue or enterprise value. A P/E ratio can reflect growth, risk, discount rates or unusual earnings. CAPE smooths real earnings across a long window to frame longer-horizon valuation; it does not reliably time short-term moves, and accounting and market composition complicate historical comparisons.',
 'Does a low P/E ratio alone establish that a share is undervalued?',
 ['Yes, the ratio guarantees excess return','No, low growth, risk or unusual earnings can explain it','Yes, it is the same as a contractual payout'],1,
 'A ratio is a clue requiring a cash-flow and risk explanation, not an investment conclusion by itself.',['marketcap']);
addLesson('equity','capital-decisions','Issuance, payouts and projects','dilution buyback npv',
 'Cedar Workshop can issue shares to fund a project or distribute surplus cash through dividends and buybacks.',
 'Issuance reduces an existing owner’s percentage but can add valuable capital; economic dilution depends on terms and use of funds. Buybacks change cash and share count, so an EPS increase need not mean greater business value. A project creates value under the NPV rule when risk-appropriately discounted incremental cash flows exceed its cost. Sunk costs differ from relevant future costs.',
 'A repurchase mechanically increases earnings per share. What should Maya check before calling it value creation?',
 ['The cash spent, price paid and financing consequences','Only the change in the denominator','Whether the shares have a colorful ticker'],0,
 'Cash leaves the business and fewer shares remain. Price, funding and alternatives determine the economic effect.',['npv']);
addLesson('housing','property','Housing services and investment','caprate rentbuy reits',
 'Maya compares renting a home, buying it and holding a listed property company. A rental property also produces operating income.',
 'A home supplies housing services as well as investment exposure. Include maintenance, taxes, insurance, transaction costs and capital opportunity cost in rent-versus-buy analysis. Cap rate compares property NOI with value before financing and appreciation. A REIT adds a tradable equity wrapper with its own leverage, management and market risks.',
 'Why is a property’s cap rate different from Maya’s complete investment return?',
 ['It excludes financing and price changes','It already guarantees all future appreciation','It is the mortgage interest rate'],0,
 'Cap rate summarizes operating income relative to property value. Debt, later capital spending and sale value still affect the investor.',['caprate']);
addLesson('housing','mortgage','Payments, equity and refinancing','amortization ltv refinance arm',
 'Maya considers a level-payment mortgage. She wants to understand the interest/principal split, her equity cushion and what happens when rates change.',
 'Interest is charged on the outstanding balance; as that balance declines, more of a fixed payment retires principal. LTV compares debt with collateral value. Adjustable rates retain reset risk for the borrower. A fixed-rate refinancing right can benefit the borrower when rates fall, leaving the lender with prepayment and reinvestment risk.',
 'Why does the principal portion of a level mortgage payment generally increase over time?',
 ['The same payment owes less interest as the balance shrinks','The contracted rate must decline every month','No principal is repaid until the final date'],0,
 'A smaller outstanding balance produces less interest, leaving more of the payment for principal.',['mortgage','ltv']);
addLesson('housing','pooling','Pools, tranches and credit protection','mbs tranches cds',
 'A lender pools mortgages and sells securities with different loss priorities. Another investor buys protection against specified credit events.',
 'Mortgage-backed securities allocate loan payments under a defined structure. Junior tranches absorb losses first, but correlated defaults can exhaust that protection and reach senior claims. Prepayments change timing even where credit is guaranteed. A credit default swap transfers defined credit-event exposure under its settlement terms; counterparty and basis risks remain.',
 'What does senior payment priority do when the pool suffers extremely large correlated losses?',
 ['It provides a cushion that can still be exhausted','It eliminates the underlying defaults','It guarantees a constant market price'],0,
 'Tranching changes loss allocation, not the total losses on the loans. A common shock can overwhelm subordination.');
addLesson('derivatives','forwards','Locking a future price','forward futures carry basis',
 'Cedar Workshop plans to buy an input later and wants to reduce price uncertainty. It compares a customized forward with an exchange-traded futures contract.',
 'A forward imposes a future exchange obligation; a futures contract is standardized and normally marked to market daily through clearing. Carry costs, income and financing connect spot and forward prices under no-arbitrage. The chosen hedge may differ from the actual exposure, leaving basis risk. Daily margin can create cash needs before the business receives the offsetting benefit.',
 'The hedge is economically useful, but its price moves against the workshop before delivery. What can it still require?',
 ['Immediate margin cash even if the eventual business exposure offsets the move','No funding until the business earns its revenue','A guarantee that the input price never changes'],0,
 'Economic risk reduction and the timing of cash demands are different. The workshop must be able to fund the hedge.',['carry']);
addLesson('derivatives','options','Rights, payoffs and profit','call put exercise short embedded',
 'Maya wants protection against a share-price decline. She compares buying a put, shorting the stock and recognizing similar rights inside other contracts.',
 'A call grants a buying right; a put grants a selling right. The premium is a cost, so a positive payoff need not be a profit. American-style exercise permits earlier exercise under its terms; European-style exercise occurs at expiration. Short-stock losses can be unlimited, while a long option ordinarily risks its premium. Refinancing and abandonment rights are embedded or real options.',
 'An option expires with a positive payoff smaller than its premium. What is the buyer’s simple net result?',
 ['A loss after subtracting the premium','A guaranteed profit because it is in the money','A free ownership share'],0,
 'Profit subtracts the cost of buying the option from its payoff. Timing and exercise terms are part of the exposure.',['call','put']);
addLesson('derivatives','replication','Matching payoffs','parity binomial riskneutral',
 'Maya compares two portfolios that produce the same future payoff. She then constructs a stock-and-cash hedge for an option with modeled up and down states.',
 'No-arbitrage ties identical payoffs to identical values when trading and financing permit replication. Put–call parity compares matching European options with stock and strike cash. A binomial hedge uses payoff differences to replicate states. Risk-neutral probabilities are pricing weights under that model, not investors’ actual forecasts of what will happen.',
 'Why can a replicable option be priced without estimating the real-world probability of an up move?',
 ['A traded stock-and-cash portfolio matches its modeled payoffs','Every up move has the same actual probability','The option seller chooses the future stock price'],0,
 'Replication links the option to prices of traded building blocks, within the model’s states and no-arbitrage conditions.',['binomial','parity']);
addLesson('derivatives','model-risk','Models and hedge limits','bs vol greeks deltahedge',
 'A dealer prices an option and adjusts a stock hedge as the underlying moves. Quoted option prices imply different volatilities across strikes.',
 'Black–Scholes–Merton uses a specific continuous price process and frictionless hedging assumptions. Implied volatility is the input that matches a market option price, not a certain realized-volatility forecast. Delta tracks first-order price exposure; gamma, theta, vega and rho address other sensitivities. Discrete hedging, jumps, costs and changing volatility leave residual risks.',
 'After setting a delta hedge, can the dealer ignore all further risk?',
 ['Yes, the trade now guarantees profit','No, delta changes and other exposures remain','Yes, gamma and volatility cease to matter'],1,
 'A delta hedge offsets a local first-order exposure. Rebalancing and other risks remain part of managing the position.');
addLesson('banking','balance-sheet','A bank’s loss cushion','balance capital liquid',
 'Cedar Workshop deposits money at a bank. The bank holds loans and securities, owes deposits and other funding, and has equity.',
 'Deposits are liabilities to the bank; loans and securities are assets. Equity is the residual loss cushion. Capital is qualifying loss-absorbing funding, not a cash pile. Liquidity concerns meeting payments now, while solvency concerns economic asset value relative to obligations. Forced sales can turn a funding problem into larger losses.',
 'A bank has valuable long-term loans but cannot obtain cash quickly enough for withdrawals. What problem appears first?',
 ['A liquidity problem','The automatic disappearance of its loans','Proof that deposits are equity'],0,
 'Asset value and immediately available cash are different. The subsequent cost of forced sales can also damage solvency.',['bank-loss']);
addLesson('banking','money-creation','Loans, deposits and policy','creation reserves policy',
 'The bank grants Cedar Workshop a loan and credits its deposit account. Payments later move deposits between banks.',
 'Lending commonly creates a loan asset and a deposit liability together; it does not create bank equity. Reserves support interbank settlement, and the simple fixed money-multiplier story misses capital, liquidity, funding, risk and demand constraints. Policy rates influence financing, demand, asset prices and expectations through delayed and uneven channels.',
 'Does creating the loan and deposit give the bank unlimited capacity to lend?',
 ['No, balance-sheet and economic constraints remain','Yes, capital and funding no longer matter','Yes, all borrowers must be approved'],0,
 'Money creation describes accounting entries, not freedom from credit losses, capital needs, liquidity or borrower demand.');
addLesson('banking','central-bank','Asset purchases and emergency funding','qe qt lender',
 'The central bank buys securities in financial markets. Later it reduces reinvestment, and an eligible bank seeks emergency funding.',
 'QE changes central-bank assets and reserve balances and can affect longer yields and portfolios. It is not automatically a household cash grant. QT reduces holdings through maturities without full reinvestment or sales. Lender-of-last-resort facilities address acute funding under specified eligibility, collateral and pricing terms; liquidity lending does not itself repair losses exceeding equity.',
 'Why can emergency funding be insufficient to save an economically insolvent institution?',
 ['More borrowing does not erase its asset losses','Emergency lending cancels every creditor’s claim','Reserves automatically become shareholders’ equity'],0,
 'Liquidity helps meet payments; restoring a deficient loss cushion requires loss allocation, recapitalization or resolution choices.');
addLesson('banking','regulation','Capital, funding and deposit protection','rwa liquidityrules insurance',
 'A supervisor assesses the bank’s loss-absorbing capital and its ability to survive funding stress. Covered depositors have a safety net.',
 'Risk-weighted capital ratios differ from non-risk-weighted leverage backstops. Liquidity coverage and stable funding rules address payment and funding horizons. Deposit insurance can reassure covered customers while weakening monitoring incentives, which supervision and capital help contain. Coverage and implementation depend on jurisdiction, account type and applicable limits.',
 'Does an illustrative regulatory capital percentage mean that the same percentage must be held as cash?',
 ['No, capital and liquid reserves serve different functions','Yes, capital is cash by definition','Yes, it is the interest rate charged on loans'],0,
 'Capital absorbs losses through qualifying claims; liquid assets support payments. They are complementary requirements.',['bank-capital']);
addLesson('institutions','issuance','Getting securities to investors','investmentbank underwriting ratings',
 'Cedar Workshop prepares a public securities offering. Underwriters gather investor demand while investors consider a credit rating.',
 'Investment banks advise on transactions and arrange issuance. Firm-commitment underwriting transfers specified distribution risk to the underwriter; bookbuilding tests demand. A rating is a credit opinion, not an insurance policy or an all-risk score. Conflicts and limited evidence require scrutiny even when established intermediaries participate.',
 'Does an investment-grade rating guarantee repayment or a stable market price?',
 ['No, it is an opinion about credit that may change','Yes, the agency reimburses any loss','Yes, it fixes the security at its issue price'],0,
 'Ratings do not remove default, interest-rate or liquidity risks. Investors still need to understand the actual claim.');
addLesson('institutions','execution','What happens when you trade?','roles spread orders pfof hft',
 'Maya sends an order through a broker. A dealer or market maker supplies a quote, and routing decisions affect her execution.',
 'A broker acts for clients; a dealer trades for itself. The ask–bid gap reflects inventory, information and processing risks. A market order prioritizes execution; a limit order imposes a price constraint but may not fill. Payment for order flow can create routing conflicts. Fast trading can supply liquidity in normal conditions yet retreat in stress.',
 'Maya needs a maximum purchase price she will accept, even if the trade does not fill. Which order best states that constraint?',
 ['A buy limit order','A market order with an assumed guaranteed price','A promise from the stock issuer'],0,
 'A limit specifies the price boundary. It trades certainty of execution for that constraint; spreads and routing still affect trading costs.');
addLesson('institutions','funds','A fund wrapper and its holdings','funds nav fees endowment',
 'Maya compares an ETF, an open-end mutual fund and an endowment-style portfolio holding less liquid assets.',
 'ETF describes an exchange-traded wrapper, not necessarily passive management. Creation and redemption normally connect its price to NAV, with liquidity and cost limits. Fees reduce compounded returns. Endowment strategies must fit governance, access, funding obligations and liquidity; copying an institution’s allocation without its capabilities can mislead.',
 'A fund is an ETF. What can Maya infer about its investment strategy?',
 ['It could be active or passive; she must inspect the mandate','It must hold an equally weighted broad stock index','It cannot use an illiquid underlying asset'],0,
 'The wrapper and the portfolio strategy are different. The actual holdings, costs and redemption mechanism determine the exposures.');
addLesson('crises','leverage','Borrowing magnifies the path','leverage margin cycle',
 'Maya funds an asset with some equity and borrowed money. Its lender can demand more collateral as conditions change.',
 'With fixed debt, gains and losses fall on a smaller equity cushion. Rising collateral supports borrowing during a boom; price declines and higher haircuts reverse that capacity. Margin demands can force liquidation before an expected recovery. Asset liquidity, funding timing and survival matter alongside final value.',
 'Why can a correct long-term valuation view fail as a leveraged trade?',
 ['A collateral call can force an early sale','Debt absorbs all losses before equity','Lenders must wait indefinitely for recovery'],0,
 'The investor needs financing throughout the path, not only a favorable eventual price.',['leverage']);
addLesson('crises','contagion','Losses and funding reinforce each other','2008 svb contagion',
 'Housing losses undermine structured claims during one crisis. In another, a bank’s long-duration securities lose market value while concentrated depositors withdraw.',
 'The global mortgage crisis combined weak underwriting, leverage, securitization and fragile funding. SVB demonstrated that low-credit-risk assets can have large duration losses, while governance and supervisory weaknesses matter. Institutions transmit distress through direct exposures, shared assets, funding and confidence. A fire sale can hurt other firms without a direct loan link.',
 'Why does holding government-backed securities not alone guarantee a bank’s resilience?',
 ['Duration losses and a funding run can still interact','Those securities eliminate every liquidity need','Deposit concentration cannot matter'],0,
 'Credit safety does not imply price stability or sufficient cash under withdrawals. Balance-sheet structure and risk management remain central.');
addLesson('crises','system','Resilience beyond individual banks','shadow resolution micro_macro',
 'Credit activity moves into funds and other nonbank institutions. Authorities also prepare plans for a large institution’s failure.',
 'Moving outside banks can relocate leverage and liquidity mismatch rather than remove them. Resolution plans aim to allocate losses while maintaining critical functions under legal tools. Microprudential supervision concerns individual institutions; macroprudential policy also addresses common exposures and feedback. Individually cautious firms can still sell together and destabilize a market.',
 'What does system-wide supervision add to checking each institution separately?',
 ['Attention to shared exposures and destabilizing feedback','A guarantee that every creditor is protected','A rule that all institutions must hold the same assets'],0,
 'Common funding and holdings can create losses through interactions even where each firm appears reasonable in isolation.');
addLesson('society','public-debt','Debt, growth and repayment sources','debtdynamics currency municipal',
 'A government finances expenditure with debt; a local authority borrows against taxes or a project’s revenues.',
 'Debt sustainability depends on interest relative to GDP growth, primary balances, refinancing and credibility. Own-currency borrowing changes constraints but does not guarantee purchasing-power returns. Municipal general-obligation and revenue bonds have different legal repayment sources. Use consistent nominal or real units in debt-ratio calculations and include relevant valuation adjustments.',
 'If GDP grows faster than effective debt interest, does that alone guarantee fiscal sustainability?',
 ['No, primary deficits and financing constraints still matter','Yes, any level of spending is permanently affordable','Yes, currencies cannot depreciate'],0,
 'A favorable growth-interest relationship helps the arithmetic but does not remove fiscal, institutional or refinancing risks.',['debt']);
addLesson('society','lifetime','Sharing risks across a lifetime','social pensions longevity',
 'Maya considers unemployment protection and retirement plans, including an income stream lasting as long as she lives.',
 'Social insurance can broaden coverage and redistribute risks difficult to insure privately. Defined contribution plans place more investment-result risk on participants; defined benefit promises shift funding risk toward the sponsor, subject to protections and solvency. Lifetime annuities pool longevity risk while leaving contract, inflation, liquidity and insurer risks to assess.',
 'What specific uncertainty can a lifetime annuity help manage?',
 ['Outliving available assets','Every future increase in living costs under all contracts','All possible insurer failures'],0,
 'It pools uncertain lifetimes. A fixed nominal promise does not automatically protect against inflation or all counterparty risk.');
addLesson('society','purpose-of-finance','Governance, advice and access','nonprofit advice democratization',
 'Maya compares member-owned financial institutions, a nonprofit and advice offered under different compensation arrangements.',
 'Nonprofits restrict distribution of profits; cooperatives are owned and governed by members. Neither form automatically solves agency problems. Adviser compensation can create conflicts, so suitability, duties and client obligations matter. Democratization ideally expands access to productive funding and useful risk protection, with understandable terms and appropriate safeguards.',
 'What is a useful sign that broader financial access is improving welfare?',
 ['People can fund worthwhile projects and protect important risks on understandable terms','Only the number of leveraged trades increases','Every participant receives a guaranteed market-beating return'],0,
 'Access matters through the decisions and protections it makes possible. Participation alone does not establish a better outcome.');
addLesson('modern','market-plumbing','Trading rules and evolving oversight','tplus capital26 stress26',
 'Maya distinguishes executing a trade from settling it, and reads announcements about bank regulation. These dated notes use the source snapshot checked in October 2026.',
 'T+1 means settlement one business day after a covered trade, not immediate execution or a calendar-day promise. The U.S. transition date was May 28, 2024, according to the SEC. The March 19, 2026 capital package was released as proposals. Separate September 30, 2026 stress-test final rules have their own timing, including two-year buffer averaging starting in 2028. Dates and timings are source facts, not calculated example amounts.',
 'Does the announcement of a final rule mean every provision already operates that day?',
 ['No, scope and effective dates must be read separately','Yes, proposals and final rules are interchangeable','Yes, every jurisdiction implements it identically'],0,
 'Release date, legal adoption and implementation can differ. Follow the relevant dated source rather than assuming a global rule.');
addLesson('modern','hidden-liquidity','Reported smoothness and real liquidity','private liquidity concentration',
 'Maya compares a privately valued loan fund with a public debt fund and a capitalization-weighted equity index.',
 'Infrequent marks can smooth reported returns without removing borrower or refinancing risk. Frequent redemption promises can exceed the liquidity of underlying loans; notice periods, gates and buffers alter that exposure. A broad index can concentrate in dominant firms and factors even with many holdings. Inspect economic risks rather than relying on labels or reported smoothness.',
 'A private fund reports very stable prices. What should Maya investigate?',
 ['How and when assets are valued, and how redemptions are funded','Whether stable marks guarantee no defaults','Only how many decimal places are reported'],0,
 'Valuation frequency can hide variation, while redemption terms can create a separate funding mismatch.');
addLesson('modern','digital-claims','The claim behind the token','stable token crypto',
 'Maya encounters a stablecoin, a tokenized security and a crypto custody service. She asks what enforceable rights each gives her.',
 'A stablecoin’s peg depends on its reserves, mechanism and redemption rights. Tokenization can change recording and transfer without removing the underlying issuer’s credit risk. Self-custody creates key-management risks; intermediary custody adds its own exposure. Smart-contract, governance and legal arrangements deserve inspection alongside market prices.',
 'What should Maya check before treating a tokenized bond as reliable?',
 ['The underlying obligation, legal rights, custody and settlement terms','Only the ledger’s speed','Whether the token’s name includes safe'],0,
 'A recording mechanism does not by itself establish credit quality, enforceable ownership or redeemability.');
addLesson('modern','changing-models','Models and shared dependencies','ai climate cyber',
 'A firm deploys an AI prediction system, estimates disaster losses from historical data and relies on a shared infrastructure provider.',
 'Backtests can fail through leakage, overfitting, costs and changing relationships. Climate and exposure changes can shift insurance distributions and correlate losses. Common payment, cloud, custody or data services create shared operational dependencies. Validation, realistic stress assumptions and recovery planning matter when past patterns and independent-failure assumptions become unreliable.',
 'Why is an excellent historical backtest insufficient evidence for live reliability?',
 ['It may exploit leakage or relationships that do not persist','Model complexity guarantees accuracy','Historical prices contain every future shock'],0,
 'Check genuinely out-of-sample performance, realistic execution and adaptation. A predictive model can change the environment in which it operates.');

// Fixed bond examples keep the familiar story while showing every intermediate amount.
export function bondLessonExample(id){
 const assumptions=[['Face value','$1,000 (assumed contract)'],['Annual coupon rate','5% (assumed contract)'],['Coupon payments per year','1 (annual)']];
 const annualCoupon=1000*.05,finalPayment=1000+annualCoupon;
 if(id==='promise')return {givens:assumptions.concat([['Term','3 years (assumed contract)']]),steps:['Convert the coupon rate: 5 ÷ 100 = 0.05.','Annual coupon = $1,000 × 0.05 ÷ 1 = $50.','Each earlier year pays the $50 coupon. Final payment = $1,000 principal + $50 coupon = $1,050.'],formula:'Coupon payment = face value × annual coupon rate ÷ payments per year',symbols:'Face value = principal promised at maturity; coupon rate = annual interest percentage; coupon payment = interest amount each payment date; maturity = repayment date.',answerText:'$50 annual coupon; $1,050 final payment'};
 if(id==='price'){const y=.06;return {givens:assumptions.concat([['Remaining annual periods','3 (assumed)'],['Required annual yield','6% (assumed market comparison)']]),steps:['Annual coupon = $1,000 × 0.05 = $50; final payment = $1,000 + $50 = $1,050.','Required yield: 6 ÷ 100 = 0.06. Gross annual discount factor = 1 + 0.06 = 1.06.',`Year 1 payment today: $50 ÷ 1.06 = $${(annualCoupon/(1+y)).toFixed(2)}.`,`Year 2 payment today: $50 ÷ 1.06² = $${(annualCoupon/(1+y)**2).toFixed(2)}.`,`Year 3 payment today: $1,050 ÷ 1.06³ = $${(finalPayment/(1+y)**3).toFixed(2)}.`,`Add the discounted payments, using full precision before rounding: $${bondPrice(1000,50,y,3).toFixed(2)}.`],formula:'P = Σₜ₌₁ᵀ C/(1+y)ᵗ + F/(1+y)ᵀ',symbols:'P = bond price today; C = coupon payment per period; F = face value; y = yield per payment period; t = payment-period index; T = total remaining periods; Σ means add the discounted payments.',answerText:'$'+bondPrice(1000,50,y,3).toFixed(2)};}
 const price=finalPayment/1.06;return {givens:assumptions.concat([['Time still remaining','1 year (assumed; earlier coupons already paid)'],['Required one-year return','6% (assumed comparison)']]),steps:['Required return: 6 ÷ 100 = 0.06; gross return factor = 1 + 0.06 = 1.06.','Remaining coupon = $1,000 × 0.05 = $50. Final payment = $1,000 + $50 = $1,050.',`Price today = $1,050 ÷ (1 + 0.06) = $${price.toFixed(2)}.`,`Gain over the purchase price = $1,050 − price = $${(finalPayment-price).toFixed(2)}.`,`Gain ÷ price = 0.06; multiply by 100 = 6% (using unrounded values).`],formula:'Price = final payment/(1 + required one-year return); return = (final payment − price)/price',symbols:'Price = what the new buyer pays today; final payment = last coupon plus principal; required return = the desired one-year gain relative to the price; 1 + return is the gross growth factor.',answerText:'$'+price.toFixed(2)};
}
